package com.dental.hospital;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.web.server.LocalServerPort;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;

import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="RUN_DB_TESTS", matches="true")
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class ConcurrencyAcceptanceTest {
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r) {
        r.add("spring.datasource.url",()->System.getenv().getOrDefault("TEST_DB_URL","jdbc:mysql://127.0.0.1:3306/dental_hospital_test?serverTimezone=UTC"));
        r.add("spring.datasource.username",()->System.getenv().getOrDefault("TEST_DB_USER","root"));
        r.add("spring.datasource.password",()->System.getenv().getOrDefault("TEST_DB_PASSWORD",""));
        r.add("JWT_SECRET",()->"test-only-secret-with-more-than-thirty-two-bytes-2026");
        r.add("ADMIN_USERNAME",()->"test_admin");
        r.add("ADMIN_PHONE",()->"13999999999");
        r.add("ADMIN_PASSWORD",()->"TestAdminPassword123!");
    }
    @Autowired JdbcTemplate db;
    @Autowired TestRestTemplate rest;
    @Autowired JwtTokens jwt;
    @Autowired Bootstrap bootstrap;
    @LocalServerPort int port;
    private static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
    private static final AtomicInteger PHONE=new AtomicInteger((int)(System.currentTimeMillis()%70_000_000));
    private static final String PASSWORD_HASH=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder().encode("Password123!");

    record User(long userId,long profileId,String token) {}
    record Fixture(long doctorId,long roomId,long departmentId,long scheduleId,long slotId,LocalDateTime start) {}
    private String base(){return "http://127.0.0.1:"+port+"/api";}
    private String unique(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,12);}
    private String sha(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new RuntimeException(e);}}
    private long insert(String sql,Object... args){GeneratedKeyHolder h=new GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p;},h);return Objects.requireNonNull(h.getKey()).longValue();}
    private long count(String sql,Object... args){return Objects.requireNonNull(db.queryForObject(sql,Long.class,args));}
    private User user(String role,long department){String name=unique("t");String phone="139"+String.format("%08d",PHONE.incrementAndGet());long id=insert("INSERT INTO sys_user(username,phone,password_hash,role) VALUES(?,?,?,?)",name,phone,PASSWORD_HASH,role);long profile=0;if(role.equals("PATIENT"))profile=insert("INSERT INTO patient_profile(user_id,name) VALUES(?,?)",id,"虚构患者");if(role.equals("DOCTOR"))profile=insert("INSERT INTO doctor_profile(user_id,employee_no,department_id,name,default_fee) VALUES(?,?,?,?,?)",id,unique("E"),department,"虚构医生",new BigDecimal("30.00"));String jti=UUID.randomUUID().toString(),token=jwt.issue(id,jti,Instant.now(),Instant.now().plusSeconds(3600));db.update("INSERT INTO auth_session(user_id,jti,token_hash,expires_at) VALUES(?,?,?,?)",id,jti,sha(token),LocalDateTime.now(ZoneOffset.UTC).plusHours(1));return new User(id,profile,token);}
    private LocalDateTime future(){return LocalDate.now(ZONE).plusDays(2).atTime(9,0).atZone(ZONE).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();}
    private Fixture fixture(int capacity,LocalDateTime start){long dep=insert("INSERT INTO department(code,name) VALUES(?,?)",unique("D"),"测试科室");long room=insert("INSERT INTO clinic_room(code,name) VALUES(?,?)",unique("R"),"测试诊室");User doctor=user("DOCTOR",dep);LocalDate day=start.atZone(ZoneOffset.UTC).withZoneSameInstant(ZONE).toLocalDate();long schedule=insert("INSERT INTO schedule(doctor_id,department_id,room_id,visit_date,starts_at,ends_at,status,fee,capacity) VALUES(?,?,?,?,?,?,'PUBLISHED',?,?)",doctor.profileId,dep,room,day,start,start.plusMinutes(30),new BigDecimal("30.00"),capacity);long slot=insert("INSERT INTO schedule_slot(schedule_id,starts_at,ends_at,capacity,remaining,fee) VALUES(?,?,?,?,?,?)",schedule,start,start.plusMinutes(30),capacity,capacity,new BigDecimal("30.00"));return new Fixture(doctor.profileId,room,dep,schedule,slot,start);}
    private HttpHeaders headers(String token,String idem){HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);h.setBearerAuth(token);if(idem!=null)h.set("Idempotency-Key",idem);return h;}
    private ResponseEntity<Map> http(String method,String path,String token,String idem,Object body){return rest.exchange(base()+path,HttpMethod.valueOf(method),new HttpEntity<>(body,headers(token,idem)),Map.class);}
    private long appointmentId(ResponseEntity<Map> r){assertEquals(200,r.getStatusCodeValue(),String.valueOf(r.getBody()));return ((Number)((Map)r.getBody().get("appointment")).get("id")).longValue();}
    private long billId(ResponseEntity<Map> r){return ((Number)((Map)((List<?>)r.getBody().get("bills")).get(0)).get("id")).longValue();}
    private List<ResponseEntity<Map>> concurrent(int n,Callable<ResponseEntity<Map>> action)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(n);CountDownLatch gate=new CountDownLatch(1);try{List<Future<ResponseEntity<Map>>> jobs=new ArrayList<>();for(int i=0;i<n;i++)jobs.add(pool.submit(()->{gate.await();return action.call();}));gate.countDown();List<ResponseEntity<Map>> result=new ArrayList<>();for(Future<ResponseEntity<Map>> f:jobs)result.add(f.get(30,TimeUnit.SECONDS));return result;}finally{pool.shutdownNow();}}

    @Test void t01ConcurrentSchedulePublish()throws Exception{Fixture f=fixture(1,future());User admin=user("ADMIN",0);db.update("UPDATE schedule SET status='DRAFT' WHERE id=?",f.scheduleId);db.update("DELETE FROM schedule_slot WHERE id=?",f.slotId);long second=insert("INSERT INTO schedule(doctor_id,department_id,room_id,visit_date,starts_at,ends_at,status,fee,capacity) VALUES(?,?,?,?,?,?,'DRAFT',?,?)",f.doctorId,f.departmentId,f.roomId,f.start.atZone(ZoneOffset.UTC).withZoneSameInstant(ZONE).toLocalDate(),f.start,f.start.plusMinutes(30),new BigDecimal("30.00"),1);List<Long> ids=List.of(f.scheduleId,second);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{List<Future<ResponseEntity<Map>>> jobs=new ArrayList<>();for(long id:ids)jobs.add(pool.submit(()->{gate.await();return http("PUT","/admin/schedules/"+id+"/publish",admin.token,null,Map.of("version",0));}));gate.countDown();int success=0;for(var job:jobs){int code=job.get(20,TimeUnit.SECONDS).getStatusCodeValue();assertTrue(code==200||code==409,"unexpected status "+code);if(code==200)success++;}assertEquals(1,success);assertEquals(1,count("SELECT COUNT(*) FROM schedule_slot WHERE schedule_id IN (?,?)",f.scheduleId,second));}finally{pool.shutdownNow();}}

    @Test void t02LastSlotOnlyOneWinner()throws Exception{Fixture f=fixture(1,future());List<User> patients=IntStream.range(0,20).mapToObj(i->user("PATIENT",0)).toList();ExecutorService pool=Executors.newFixedThreadPool(20);CountDownLatch gate=new CountDownLatch(1);try{List<Future<ResponseEntity<Map>>> jobs=new ArrayList<>();for(User p:patients)jobs.add(pool.submit(()->{gate.await();return http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));}));gate.countDown();int success=0;for(var job:jobs){int code=job.get(40,TimeUnit.SECONDS).getStatusCodeValue();assertTrue(code==200||code==409,"unexpected status "+code);if(code==200)success++;}assertEquals(1,success);assertEquals(0,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));assertEquals(1,count("SELECT COUNT(*) FROM appointment WHERE slot_id=?",f.slotId));assertEquals(1,count("SELECT COUNT(*) FROM bill b JOIN appointment a ON a.id=b.appointment_id WHERE a.slot_id=?",f.slotId));}finally{pool.shutdownNow();}}

    @Test void t03SamePatientOverlapAndAdjacent()throws Exception{LocalDateTime start=future();Fixture a=fixture(1,start),b=fixture(1,start),adjacent=fixture(1,start.plusMinutes(30));User p=user("PATIENT",0);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{List<Future<ResponseEntity<Map>>> jobs=new ArrayList<>();for(long slot:List.of(a.slotId,b.slotId))jobs.add(pool.submit(()->{gate.await();return http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(slot)));}));gate.countDown();int success=0;for(var job:jobs){int code=job.get(20,TimeUnit.SECONDS).getStatusCodeValue();assertTrue(code==200||code==409,"unexpected status "+code);if(code==200)success++;}assertEquals(1,success);assertEquals(200,http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(adjacent.slotId))).getStatusCodeValue());}finally{pool.shutdownNow();}}

    @Test void t04IdempotencyAndConflict(){Fixture f=fixture(2,future());User p=user("PATIENT",0);String k=UUID.randomUUID().toString();Map<String,String> request=Map.of("slotId",Long.toString(f.slotId));ResponseEntity<Map> first=http("POST","/appointments",p.token,k,request),again=http("POST","/appointments",p.token,k,request);assertEquals(appointmentId(first),appointmentId(again));assertEquals(409,http("POST","/appointments",p.token,k,Map.of("slotId",Long.toString(f.slotId),"symptomSummary","different")).getStatusCodeValue());assertEquals(1,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));}

    @Test void t05ExpiryWinsAtDeadline() throws Exception {Fixture f=fixture(1,future());User p=user("PATIENT",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));long appt=appointmentId(booked),bill=billId(booked);db.update("UPDATE appointment SET pay_expires_at=UTC_TIMESTAMP(3)-INTERVAL 1 SECOND WHERE id=?",appt);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{Future<ResponseEntity<Map>> pay=pool.submit(()->{gate.await();return http("POST","/bills/"+bill+"/mock-pay",p.token,UUID.randomUUID().toString(),Map.of());});Future<?> expire=pool.submit(()->{gate.await();bootstrap.expire();return null;});gate.countDown();assertNotEquals(200,pay.get(20,TimeUnit.SECONDS).getStatusCodeValue());expire.get(20,TimeUnit.SECONDS);assertEquals("EXPIRED",db.queryForObject("SELECT status FROM appointment WHERE id=?",String.class,appt));assertEquals(1,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));assertEquals(0,count("SELECT COUNT(*) FROM payment_record WHERE bill_id=?",bill));}finally{pool.shutdownNow();}}

    @Test void t06RepeatCancelRefundAndRebook(){Fixture f=fixture(1,future());User p=user("PATIENT",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));long appt=appointmentId(booked),bill=billId(booked);assertEquals(200,http("POST","/bills/"+bill+"/mock-pay",p.token,UUID.randomUUID().toString(),Map.of()).getStatusCodeValue());assertEquals(200,http("PUT","/appointments/"+appt+"/cancel",p.token,null,Map.of()).getStatusCodeValue());assertEquals(200,http("PUT","/appointments/"+appt+"/cancel",p.token,null,Map.of()).getStatusCodeValue());assertEquals(1,count("SELECT COUNT(*) FROM refund_record WHERE bill_id=?",bill));assertEquals(1,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));assertEquals(200,http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId))).getStatusCodeValue());}

    @Test void t09RecordSubmitOnceAndOwnership(){LocalDateTime start=LocalDateTime.now(ZoneOffset.UTC).plusMinutes(20);Fixture f=fixture(1,start);User p=user("PATIENT",0),admin=user("ADMIN",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));long appt=appointmentId(booked),bill=billId(booked);assertEquals(200,http("POST","/bills/"+bill+"/mock-pay",p.token,UUID.randomUUID().toString(),Map.of()).getStatusCodeValue());assertEquals(200,http("PUT","/admin/appointments/"+appt+"/check-in",admin.token,null,Map.of()).getStatusCodeValue());long doctorUser=count("SELECT user_id FROM doctor_profile WHERE id=?",f.doctorId);String jti=UUID.randomUUID().toString(),token=jwt.issue(doctorUser,jti,Instant.now(),Instant.now().plusSeconds(3600));db.update("INSERT INTO auth_session(user_id,jti,token_hash,expires_at) VALUES(?,?,?,?)",doctorUser,jti,sha(token),LocalDateTime.now(ZoneOffset.UTC).plusHours(1));assertEquals(200,http("PUT","/doctor/appointments/"+appt+"/start",token,null,Map.of()).getStatusCodeValue());long item=insert("INSERT INTO treatment_item(code,name,fee) VALUES(?,?,?)",unique("I"),"检查",new BigDecimal("20.00"));Map<String,Object> body=Map.of("chiefComplaint","虚构主诉","examination","虚构检查","advice","虚构医嘱","items",List.of(Map.of("itemId",Long.toString(item),"quantity","1")));String key=UUID.randomUUID().toString();assertEquals(200,http("POST","/doctor/appointments/"+appt+"/medical-record/submit",token,key,body).getStatusCodeValue());assertEquals(200,http("POST","/doctor/appointments/"+appt+"/medical-record/submit",token,key,body).getStatusCodeValue());assertEquals(1,count("SELECT COUNT(*) FROM medical_record WHERE appointment_id=?",appt));assertEquals(1,count("SELECT COUNT(*) FROM bill WHERE appointment_id=? AND type='TREATMENT'",appt));User other=user("PATIENT",0);assertEquals(404,http("GET","/appointments/"+appt,other.token,null,null).getStatusCodeValue());assertEquals(404,http("GET","/bills/"+bill,other.token,null,null).getStatusCodeValue());long recordId=count("SELECT id FROM medical_record WHERE appointment_id=?",appt);assertEquals(404,http("GET","/medical-records/"+recordId,other.token,null,null).getStatusCodeValue());assertEquals(403,http("GET","/medical-records/"+recordId,admin.token,null,null).getStatusCodeValue());}

    @Test void t04ConcurrentSameKeyReturnsOneResult() throws Exception {Fixture f=fixture(2,future());User p=user("PATIENT",0);String idem=UUID.randomUUID().toString();List<ResponseEntity<Map>> results=concurrent(2,()->http("POST","/appointments",p.token,idem,Map.of("slotId",Long.toString(f.slotId))));assertEquals(200,results.get(0).getStatusCodeValue());assertEquals(200,results.get(1).getStatusCodeValue());assertEquals(appointmentId(results.get(0)),appointmentId(results.get(1)));assertEquals(1,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));}

    @Test void t05BeforeAndAtDeadline(){Fixture early=fixture(1,future());User p=user("PATIENT",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(early.slotId)));long appt=appointmentId(booked),bill=billId(booked);bootstrap.expire();assertEquals(200,http("POST","/bills/"+bill+"/mock-pay",p.token,UUID.randomUUID().toString(),Map.of()).getStatusCodeValue());assertEquals("BOOKED",db.queryForObject("SELECT status FROM appointment WHERE id=?",String.class,appt));Fixture due=fixture(1,future());User p2=user("PATIENT",0);ResponseEntity<Map> second=http("POST","/appointments",p2.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(due.slotId)));long expired=appointmentId(second),dueBill=billId(second);db.update("UPDATE appointment SET pay_expires_at=UTC_TIMESTAMP(3) WHERE id=?",expired);assertEquals(409,http("POST","/bills/"+dueBill+"/mock-pay",p2.token,UUID.randomUUID().toString(),Map.of()).getStatusCodeValue());bootstrap.expire();assertEquals("EXPIRED",db.queryForObject("SELECT status FROM appointment WHERE id=?",String.class,expired));}

    @Test void t06ConcurrentCancelOnlyOneRefund() throws Exception {Fixture f=fixture(1,future());User p=user("PATIENT",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));long appt=appointmentId(booked),bill=billId(booked);assertEquals(200,http("POST","/bills/"+bill+"/mock-pay",p.token,UUID.randomUUID().toString(),Map.of()).getStatusCodeValue());List<ResponseEntity<Map>> results=concurrent(2,()->http("PUT","/appointments/"+appt+"/cancel",p.token,null,Map.of()));for(var r:results)assertEquals(200,r.getStatusCodeValue());assertEquals(1,count("SELECT COUNT(*) FROM refund_record WHERE bill_id=?",bill));assertEquals(1,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));}

    @Test void t14StatsCountCancelledOnce(){Fixture f=fixture(1,future());User p=user("PATIENT",0),admin=user("ADMIN",0);ResponseEntity<Map> booked=http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId)));long appt=appointmentId(booked);http("PUT","/appointments/"+appt+"/cancel",p.token,null,Map.of());LocalDate date=f.start.atZone(ZoneOffset.UTC).withZoneSameInstant(ZONE).toLocalDate();ResponseEntity<Map> response=http("GET","/admin/statistics/appointments?from="+date+"&to="+date,admin.token,null,null);assertEquals(200,response.getStatusCodeValue());List<Map> data=(List<Map>)response.getBody().get("items");Map line=data.stream().filter(x->((Number)x.get("department_id")).longValue()==f.departmentId).findFirst().orElseThrow();assertEquals(1,((Number)line.get("total")).intValue());assertEquals(1,((Number)line.get("cancelled")).intValue());}

    @Test void jwtTamperingRevocationAndAdminBoundary(){User a=user("ADMIN",0),p=user("PATIENT",0);assertEquals(200,http("GET","/auth/me",p.token,null,null).getStatusCodeValue());String tampered=p.token.substring(0,p.token.length()-2)+"xx";assertEquals(401,http("GET","/auth/me",tampered,null,null).getStatusCodeValue());assertEquals(403,http("GET","/admin/users",p.token,null,null).getStatusCodeValue());assertEquals(200,http("PUT","/admin/users/"+p.userId+"/status",a.token,null,Map.of("status","DISABLED","reason","验收测试")).getStatusCodeValue());assertEquals(401,http("GET","/auth/me",p.token,null,null).getStatusCodeValue());assertEquals(1,count("SELECT COUNT(*) FROM admin_operation_log WHERE operator_id=? AND target_id=? AND action='USER_STATUS'",a.userId,p.userId));}

    @Test void adminCapacityCannotDropBelowUsed(){Fixture f=fixture(2,future());User a=user("ADMIN",0),p=user("PATIENT",0);assertEquals(200,http("POST","/appointments",p.token,UUID.randomUUID().toString(),Map.of("slotId",Long.toString(f.slotId))).getStatusCodeValue());assertEquals(409,http("PUT","/admin/slots/"+f.slotId+"/capacity",a.token,null,Map.of("capacity",0)).getStatusCodeValue());assertEquals(200,http("PUT","/admin/slots/"+f.slotId+"/capacity",a.token,null,Map.of("capacity",1)).getStatusCodeValue());assertEquals(0,count("SELECT remaining FROM schedule_slot WHERE id=?",f.slotId));assertEquals(409,http("PUT","/admin/rooms/"+f.roomId,a.token,null,Map.of("enabled",false)).getStatusCodeValue());}
}
